# Data stored as (XM note, instrument, volume-column byte, effect, effect parameter).
seq={}
def put(bar,row,ch,n=None,i=0,v=None,fx=0,p=0):
    assert 0<=bar<64 and 0<=row<16 and 0<=ch<CH,(bar,row,ch)
    if (bar,row,ch) in seq: raise ValueError(('collision',bar,row,ch,seq[(bar,row,ch)]))
    if v is not None: assert 0<=v<=64
    seq[(bar,row,ch)]=(nt(n) if n is not None else 0,i,(v+0x10 if v is not None else 0),fx,p)
def at(absrow,ch,n,i,v=None,fx=0,p=0):
