    out+=struct.pack('<I',40)
    out+=bytes(96)
    out+=points(z.env)
    out+=points([(0,32),(25,32)])
    out+=struct.pack('<BB',len(z.env),2)
    out+=struct.pack('<BBB',z.sustain if z.sustain is not None else 0,0,0)
    out+=struct.pack('<BBB',0,0,0)
    out+=struct.pack('<BB',1+(2 if z.sustain is not None else 0) if z.env else 0,0)
    out+=struct.pack('<BBBB',0,0,0,0)
    out+=struct.pack('<HH',z.fadeout,0)
    out+=bytes(20)
    assert len(out)==263,len(out)
    typeflag=0x10+(1 if z.loop else 0)
    start=(len(z.signal)-z.period)*2 if z.loop else 0
    looplen=z.period*2 if z.loop else 0
    out+=struct.pack('<IIIBbBBbB22s',len(z.signal)*2,start,looplen,z.volume,0,typeflag,z.panning,z.relative,0,fixed(z.sample_name,22))
    delta=np.diff(np.concatenate(([0],z.signal.astype(np.int32)))).astype('<i2')
    out+=delta.tobytes()
    return bytes(out)

