        return .64*np.sin(p+.22*br*np.sin(2*p))+.22*br*np.sin(3*p)+.12*br*np.sin(5*p)+.11*np.sin(2*p)
    if kind=='arp2':
        # Rounded, narrow pulse with an intentionally hollow spectrum.
        v=.32*np.sin(p)+sum((.47/k)*np.sin(np.pi*k*.30)*np.sin(k*p-np.pi*k*.30) for k in range(1,11))
        return v+.11*br*np.sin(7*p)
    if kind=='pad':
        return .69*np.sin(p)+.21*np.sin(2*p-.30)+.095*np.sin(3*p+.55)+.035*np.sin(4*p)
    if kind=='lead':
        v=.52*np.sin(p)+sum((.33/k)*(1 if k%2 else .27)*np.sin(k*p+.15*k) for k in range(2,12))
        return np.tanh((1.20+.23*br)*v)
    if kind=='echo':
        return .79*np.sin(p)+.15*np.sin(2*p+.40)+.08*np.sin(3*p)
    if kind=='bell':
        return .72*np.sin(p+.25*br*np.sin(4*p))+.29*br*np.sin(2*p)+.16*br*np.sin(4*p)+.045*br*np.sin(6*p)
    if kind=='stab':
        return np.tanh(.82*np.sin(p)+.23*br*np.sin(2*p)+.17*br*np.sin(3*p)+.075*br*np.sin(5*p))
    if kind=='prism':
        return np.tanh(.56*np.sin(p)+.34*np.sin(2*p+.34)+.22*br*np.sin(3*p)+.12*br*np.sin(4*p)+.055*br*np.sin(7*p))
    if kind=='sine': return np.sin(p)
    raise ValueError(kind)
def loop_wave(kind,cycles=9,period=128,peak=.75):
    # Same phase each cycle; at final cycle the waveform is precisely stationary.
    segments=[]
    phase=np.arange(period)/period
    for i in range(cycles):
        br=1.+ (1.7 if kind in ('arp','arp2','bell','prism','bass') else .24)*np.exp(-i/1.35)
        seg=waveshape(kind,phase,br)
        if kind=='bass': seg*=1+.12*np.exp(-i*.9)
        if kind=='lead': seg*=.95+.05*np.exp(-i*.7)
        segments.append(seg)
    data=np.concatenate(segments)
    # The sound shaping is done in a little waveform preface and in an XM volume envelope.
    return norm(data,peak)

def smooth_noise(length, rate, highpass, lowpass=None):
    # FFT sculpting creates crisp, deterministic natural noise without an external asset.
    n=rng.standard_normal(length)
    fft=np.fft.rfft(n)
    freqs=np.fft.rfftfreq(length,1/rate)
    mask=(1-np.exp(-(freqs/ max(1,highpass))**3))
    if lowpass: mask*=np.exp(-(freqs/lowpass)**4)
    out=np.fft.irfft(fft*mask,n=length)
    return out/(max(1e-9,np.std(out)))

def kick():
    rate=16726; t=np.arange(round(rate*.44))/rate
    freq=45+107*np.exp(-t*29)+25*np.exp(-t*130)
    phase=2*np.pi*np.cumsum(freq)/rate
    body=(.95*np.sin(phase)+.18*np.sin(2*phase))*np.exp(-t*13.5)
    click=smooth_noise(len(t),rate,1800,5800)*np.exp(-t*290)*.13
    return norm(body+click,.93)
def snare():
    rate=16726; t=np.arange(round(rate*.33))/rate
    noise=(smooth_noise(len(t),rate,820,6900)*.62+smooth_noise(len(t),rate,3000,7300)*.19)
    flutter=(1+.19*np.sin(2*np.pi*61*t))
    body=(.55*np.sin(2*np.pi*(174*t+42*t*t))+.2*np.sin(2*np.pi*294*t))*np.exp(-t*24)
    return norm(noise*np.exp(-t*17)*flutter+body,.81)
def hat(open=False):
    rate=33452; dur=.31 if open else .105
    t=np.arange(round(rate*dur))/rate
    n=smooth_noise(len(t),rate,4600,15500)
    metal=sum(.11*np.sin(2*np.pi*f*t+ph) for f,ph in [(4921,0),(6659,1),(8533,.6),(10529,2)])
    env=np.exp(-t*(15 if open else 49))
    env*=1-np.exp(-t*1900)
    return norm((n*.66+metal)*env,.63 if open else .53)
def clap():
    rate=16726;t=np.arange(round(rate*.36))/rate
    n=smooth_noise(len(t),rate,1300,7500)
    pulse=(.7*np.exp(-t*90)+.75*np.exp(-np.maximum(0,t-.020)*90)*(t>=.020)+.9*np.exp(-np.maximum(0,t-.038)*72)*(t>=.038))
    tail=.3*np.exp(-t*13)
    return norm(n*(pulse+tail)*(1-np.exp(-t*750)),.7)
def cymbal():
    rate=33452;t=np.arange(round(rate*1.5))/rate
    noise=.65*smooth_noise(len(t),rate,3300,15600)+.35*smooth_noise(len(t),rate,8700,16000)
    # washing cymbal that dies away, not white-noise left playing through the next phrase
    env=(1-np.exp(-t*650))*np.exp(-t*3.55)
    env*=1+.16*np.sin(2*np.pi*13*t)
    return norm(noise*env,.63)
def tom():
    rate=16726;t=np.arange(round(rate*.25))/rate
    f=107+145*np.exp(-t*28)
    return norm((np.sin(2*np.pi*np.cumsum(f)/rate)+.18*np.sin(4*np.pi*np.cumsum(f)/rate))*np.exp(-t*16)+.04*smooth_noise(len(t),rate,1200,6000)*np.exp(-t*130),.8)
def tick():
    rate=33452;t=np.arange(round(rate*.08))/rate
    return norm((smooth_noise(len(t),rate,2600,12000)*.23+np.sin(2*np.pi*1610*t)*.7)*np.exp(-t*91),.6)
def riser():
    rate=16726;t=np.arange(round(rate*1.56))/rate
    white=rng.standard_normal(len(t))
    # Moving noisy ring harmonics: pitch and level both rise toward the transition.
    f=320+4900*(t/t[-1])**2
    p=2*np.pi*np.cumsum(f)/rate
    chunks=np.convolve(white, np.ones(13)/13,mode='same')
    env=(t/t[-1])**2.5
    sig=(.49*np.sin(p)+.30*np.sin(p*1.55)+.22*chunks)*env
    sig[-180:]*=np.linspace(1,0,180)
    return norm(sig,.56)

class Instrument:
    def __init__(self,name,signal,panning=128,volume=64,relative=0,loop=False,period=128,
                 env=None,sustain=None,fadeout=300,name_s=None):
        self.name=name; self.signal=np.clip(np.rint(signal*32700),-32768,32767).astype('<i2')
        self.panning=panning;self.volume=volume;self.relative=relative
        self.loop=loop;self.period=period;self.env=env or []
        self.sustain=sustain; self.fadeout=fadeout
        self.sample_name=name_s or name

