for b,c in enumerate(chords):
    S=section(b); notes=CHORD[c]['pad']
    vol= 25 if S=='intro' else (24 if S=='break' else (27 if S=='outro' else 30))
    if S=='reprise' and b%8>=4: vol=31
    for j,nn in enumerate(notes):
        nbar(b,0,10+j,nn,I_PAD,vol-(2 if j==0 else 0),8,[77,128,184][j])
        # A short release under the pickup into the next bar
        keyoff(b*16+14,10+j)

