    S=section(b); root=nt(CHORD[c]['root']); fifth=nt(CHORD[c]['bass5']); octv=root+12
    if S=='intro':
        if b>=1:
            for r,n,v in ([(0,root,44),(8,root,38)] if b<3 else [(0,root,44),(6,fifth,38),(8,root,44),(12,octv,35)]):
                nbar(b,r,6,n,I_BASS,v)
    elif S=='break':
        for r,n,v in [(0,root,39),(6,fifth,29),(8,root,39),(12,octv,29)]:nbar(b,r,6,n,I_BASS,v)
    elif S=='outro':
        pattern=[(0,root,43),(4,octv,31),(8,root,44),(12,fifth,37)]
        if b>=62:pattern+=[(14,octv,40)]
        for r,n,v in pattern:nbar(b,r,6,n,I_BASS,v)
    else:
        bassline=[(0,root,52),(3,octv,35),(4,root,45),(7,fifth,35),
                  (8,root,53),(10,octv,33),(12,fifth,43),(14,root,39)]
        if S=='lift': bassline=[(0,root,51),(3,octv,38),(4,root,45),(6,fifth,32),(8,root,51),(11,octv,36),(12,fifth,42),(15,octv,28)]
        if S=='reprise' and b%4==3: bassline[-1]=(14,fifth+12,39)
