# Returns the nearest following monophonic attack, so key-offs only land in actual rests.
def leadphrase(b,phrase,instr,velocity,echo=True,melchan=13):
    entries=[(r,nt(n)) for r,n in phrase]
    for idx,(r,n) in enumerate(entries):
        vel=velocity+(3 if r in (0,8) else 0)-(3 if r in (6,14) else 0)
        nbar(b,r,melchan,n,instr,vel)
        next_r=entries[idx+1][0] if idx+1<len(entries) else 17
        # echo follows a melody without overpowering the principal theme
        if echo and (r in (0,3,4,8,11,12) or (idx%3==0)):
            er=b*16+r+3
            if er<(b+1)*16 or r>11:
                channel=15 if (idx+b)%2==0 else 16
                eins=I_ECHO_L if channel==15 else I_ECHO_R
                at(er,channel,n,eins,18 if vel>=45 else 15)
                if r in (0,8) and section(b)=='reprise':
                    er2=b*16+r+6
                    channel2=16 if channel==15 else 15
                    at(er2,channel2,n,I_ECHO_R if channel2==16 else I_ECHO_L,11)
        if next_r-r>4:
            keyoff(b*16+r+min(4,next_r-1-r),melchan)
    # One fast micro-slide at thematic peak; note-less effect continues previous pitch.
    if len(entries)>0 and entries[0][0]==0 and b%8==5:
        # vibrato on the long note on row 8 where it makes sense, if the row is unoccupied
        if (b,9,melchan) not in seq:
            put(b,9,melchan,None,0,None,4,0x32)

