# An actual XM file, not a long audio sample. This packs real note cells and 19 synthesized instruments.
def fixed(s,length): return s.encode('ascii','replace')[:length].ljust(length,b' ')
def instrument_bytes(z):
    def points(vals):
        vals=vals[:12]
        return b''.join(struct.pack('<HH',max(0,int(x)),max(0,min(64,int(y)))) for x,y in vals)+b'\0'*(48-len(vals)*4)
    out=bytearray()
    out+=struct.pack('<I22sBH',263,fixed(z.name,22),0,1)
    out+=struct.pack('<I',40)
    out+=bytes(96)
    out+=points(z.env)
    out+=points([(0,32),(25,32)])
    out+=struct.pack('<BB',len(z.env),2)
    out+=struct.pack('<BBB',z.sustain if z.sustain is not None else 0,0,0)
    out+=struct.pack('<BBB',0,0,0)
    out+=struct.pack('<BB',1+(2 if z.sustain is not None else 0) if z.env else 0,0)
    out+=struct.pack('<BBBB',0,0,0,0)
    out+=struct.pack('<HH',z.fadeout,0)
    out+=bytes(20)
    assert len(out)==263,len(out)
    typeflag=0x10+(1 if z.loop else 0)
    start=(len(z.signal)-z.period)*2 if z.loop else 0
    looplen=z.period*2 if z.loop else 0
    out+=struct.pack('<IIIBbBBbB22s',len(z.signal)*2,start,looplen,z.volume,0,typeflag,z.panning,z.relative,0,fixed(z.sample_name,22))
    delta=np.diff(np.concatenate(([0],z.signal.astype(np.int32)))).astype('<i2')
    out+=delta.tobytes()
    return bytes(out)

def write_xm(path):
    data=bytearray()
    data+=b'Extended Module: '+fixed('FILAMENT / afterglow',20)+b'\x1a'+fixed('FastTracker II',20)
    data+=struct.pack('<HI8H',0x104,276,32,2,CH,PN,len(inst)-1,1,SPEED,BPM)
    data+=bytes(list(range(PN))+[0]*(256-PN))
    assert len(data)==336,len(data)
    for pat in range(PN):
        cells=bytearray()
        for row in range(32):
            bar=pat*2+row//16
            for ch in range(CH):
                cells.extend(seq.get((bar,row%16,ch),(0,0,0,0,0)))
        data+=struct.pack('<IBHH',9,0,32,len(cells))
        data+=cells
    for z in inst[1:]:data+=instrument_bytes(z)
    Path(path).write_bytes(data)
    return len(data)

if __name__=='__main__':
    print('events',len(seq),'instruments',len(inst)-1,'output bytes',write_xm(OUT/'tune.xm'))
    for s in ('intro','verse','break','lift','reprise','outro'):
        print(s,sum(1 for b,r,ch in seq if section(b)==s))
